INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-ssat-quantitative-370','SSAT','quantitative','mcq',2,NULL,'What is the area of the rectangle, in square centimeters?','<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 260 160" width="260" height="160" font-family="Helvetica,Arial,sans-serif" font-size="12" fill="#1f2937"><rect x="55" y="36.25" width="150" height="87.5" fill="#e0e7ff" stroke="#1f2937" stroke-width="2"/><text x="130" y="30.25" text-anchor="middle">12 cm</text><text x="213" y="84" >7 cm</text></svg>','["96","84","19","38"]',1,'Area = 12 × 7.',1,0);
