INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-ssat-quantitative-374','SSAT','quantitative','mcq',4,NULL,'The figure shows two angles on a straight line. What is the value of x?','<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 260 130" width="260" height="130" font-family="Helvetica,Arial,sans-serif" font-size="12" fill="#1f2937"><line x1="30" y1="100" x2="230" y2="100" stroke="#1f2937" stroke-width="2"/><line x1="130" y1="100" x2="211.5677008332985" y2="61.96435644333705" stroke="#1f2937" stroke-width="2"/><text x="148" y="92" font-weight="700">155°</text><text x="92" y="92" font-weight="700">x°</text></svg>','["25","155","35","205"]',0,'Angles on a line sum to 180°: 180 − 155 = 25.',1,0);
