INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-ssat-quantitative-381','SSAT','quantitative','mcq',4,NULL,'In the right triangle shown, what is the length of the hypotenuse (the side marked ?)','<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 260 190" width="260" height="190" font-family="Helvetica,Arial,sans-serif" font-size="12" fill="#1f2937"><polygon points="50,150 200,150 50,106.25" fill="#dcfce7" stroke="#1f2937" stroke-width="2"/><path d="M50 136 h14 v14" fill="none" stroke="#1f2937"/><text x="42" y="128.125" text-anchor="end">7</text><text x="125" y="168" text-anchor="middle">24</text><text x="133" y="124.125" font-weight="700">?</text></svg>','["24","31","26","25"]',3,'7² + 24² = 25², so the hypotenuse is 25.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-ssat-quantitative-382','SSAT','quantitative','mcq',3,NULL,'The circle has radius 8. What is its circumference?','<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 220 180" width="220" height="180" font-family="Helvetica,Arial,sans-serif" font-size="12" fill="#1f2937"><circle cx="110" cy="90" r="66" fill="#fef3c7" stroke="#1f2937" stroke-width="2"/><circle cx="110" cy="90" r="3" fill="#1f2937"/><line x1="110" y1="90" x2="176" y2="90" stroke="#1f2937" stroke-width="2"/><text x="143" y="84" text-anchor="middle">8</text></svg>','["16π","8π","32π","64π"]',0,'Circumference = 2πr.',1,0);
