INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-ssat-quantitative-384','SSAT','quantitative','mcq',4,NULL,'The figure shows two angles on a straight line. What is the value of x?','<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 260 130" width="260" height="130" font-family="Helvetica,Arial,sans-serif" font-size="12" fill="#1f2937"><line x1="30" y1="100" x2="230" y2="100" stroke="#1f2937" stroke-width="2"/><line x1="130" y1="100" x2="78.37812072840585" y2="26.27631601399075" stroke="#1f2937" stroke-width="2"/><text x="148" y="92" font-weight="700">55°</text><text x="92" y="92" font-weight="700">x°</text></svg>','["55","125","305","35"]',1,'Angles on a line sum to 180°: 180 − 55 = 125.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-ssat-quantitative-385','SSAT','quantitative','mcq',2,NULL,'What number does point P represent on the number line?','<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 80" width="320" height="80" font-family="Helvetica,Arial,sans-serif" font-size="12" fill="#1f2937"><line x1="20" y1="40" x2="300" y2="40" stroke="#1f2937" stroke-width="2"/><line x1="20" y1="34" x2="20" y2="46" stroke="#1f2937"/><text x="20" y="62" text-anchor="middle" font-size="11">-6</text><line x1="43.33333333333333" y1="34" x2="43.33333333333333" y2="46" stroke="#1f2937"/><text x="43.33333333333333" y="62" text-anchor="middle" font-size="11">-5</text><line x1="66.66666666666666" y1="34" x2="66.66666666666666" y2="46" stroke="#1f2937"/><text x="66.66666666666666" y="62" text-anchor="middle" font-size="11">-4</text><line x1="90" y1="34" x2="90" y2="46" stroke="#1f2937"/><text x="90" y="62" text-anchor="middle" font-size="11">-3</text><line x1="113.33333333333333" y1="34" x2="113.33333333333333" y2="46" stroke="#1f2937"/><text x="113.33333333333333" y="62" text-anchor="middle" font-size="11">-2</text><line x1="136.66666666666669" y1="34" x2="136.66666666666669" y2="46" stroke="#1f2937"/><text x="136.66666666666669" y="62" text-anchor="middle" font-size="11">-1</text><line x1="160" y1="34" x2="160" y2="46" stroke="#1f2937"/><text x="160" y="62" text-anchor="middle" font-size="11">0</text><line x1="183.33333333333334" y1="34" x2="183.33333333333334" y2="46" stroke="#1f2937"/><text x="183.33333333333334" y="62" text-anchor="middle" font-size="11">1</text><line x1="206.66666666666666" y1="34" x2="206.66666666666666" y2="46" stroke="#1f2937"/><text x="206.66666666666666" y="62" text-anchor="middle" font-size="11">2</text><line x1="230" y1="34" x2="230" y2="46" stroke="#1f2937"/><text x="230" y="62" text-anchor="middle" font-size="11">3</text><line x1="253.33333333333334" y1="34" x2="253.33333333333334" y2="46" stroke="#1f2937"/><text x="253.33333333333334" y="62" text-anchor="middle" font-size="11">4</text><line x1="276.66666666666663" y1="34" x2="276.66666666666663" y2="46" stroke="#1f2937"/><text x="276.66666666666663" y="62" text-anchor="middle" font-size="11">5</text><line x1="300" y1="34" x2="300" y2="46" stroke="#1f2937"/><text x="300" y="62" text-anchor="middle" font-size="11">6</text><circle cx="230" cy="40" r="5" fill="#ef4444"/><text x="230" y="26" text-anchor="middle" font-weight="700">P</text></svg>','["4","3","-3","2"]',1,'P is at 3.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-ssat-quantitative-386','SSAT','quantitative','mcq',3,NULL,'Each small square has an area of 1 square unit. What is the total shaded area?','<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 164 164" width="164" height="164" font-family="Helvetica,Arial,sans-serif" font-size="12" fill="#1f2937"><rect x="34" y="58" width="24" height="24" fill="#a5b4fc"/><rect x="34" y="106" width="24" height="24" fill="#a5b4fc"/><rect x="58" y="58" width="24" height="24" fill="#a5b4fc"/><rect x="10" y="10" width="24" height="24" fill="#a5b4fc"/><rect x="106" y="82" width="24" height="24" fill="#a5b4fc"/><rect x="106" y="130" width="24" height="24" fill="#a5b4fc"/><rect x="58" y="130" width="24" height="24" fill="#a5b4fc"/><rect x="58" y="82" width="24" height="24" fill="#a5b4fc"/><rect x="34" y="82" width="24" height="24" fill="#a5b4fc"/><rect x="82" y="82" width="24" height="24" fill="#a5b4fc"/><rect x="34" y="130" width="24" height="24" fill="#a5b4fc"/><rect x="10" y="130" width="24" height="24" fill="#a5b4fc"/><rect x="10" y="106" width="24" height="24" fill="#a5b4fc"/><rect x="58" y="106" width="24" height="24" fill="#a5b4fc"/><line x1="10" y1="10" x2="10" y2="154" stroke="#9ca3af"/><line x1="10" y1="10" x2="154" y2="10" stroke="#9ca3af"/><line x1="34" y1="10" x2="34" y2="154" stroke="#9ca3af"/><line x1="10" y1="34" x2="154" y2="34" stroke="#9ca3af"/><line x1="58" y1="10" x2="58" y2="154" stroke="#9ca3af"/><line x1="10" y1="58" x2="154" y2="58" stroke="#9ca3af"/><line x1="82" y1="10" x2="82" y2="154" stroke="#9ca3af"/><line x1="10" y1="82" x2="154" y2="82" stroke="#9ca3af"/><line x1="106" y1="10" x2="106" y2="154" stroke="#9ca3af"/><line x1="10" y1="106" x2="154" y2="106" stroke="#9ca3af"/><line x1="130" y1="10" x2="130" y2="154" stroke="#9ca3af"/><line x1="10" y1="130" x2="154" y2="130" stroke="#9ca3af"/><line x1="154" y1="10"