INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-ssat-reading-387','SSAT','reading','mcq',2,'Every morning before sunrise, Tomás walked to the harbor to help his uncle sort the night''s catch. At first the cold bit through his gloves and the smell made his eyes water. But as weeks passed he learned to tell a mackerel from a herring by touch alone, and the fishermen began to nod at him as one of their own. By spring, he no longer dreaded the alarm clock.','Why did Tomás stop dreading the alarm clock?',NULL,'["He bought a better coat.","He grew skilled and accepted at the harbor.","His uncle paid him more.","The harbor moved closer."]',1,'His skills and acceptance grew.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-ssat-reading-388','SSAT','reading','mcq',3,'Every morning before sunrise, Tomás walked to the harbor to help his uncle sort the night''s catch. At first the cold bit through his gloves and the smell made his eyes water. But as weeks passed he learned to tell a mackerel from a herring by touch alone, and the fishermen began to nod at him as one of their own. By spring, he no longer dreaded the alarm clock.','The phrase "one of their own" suggests that the fishermen',NULL,'["felt sorry for him","treated him as part of their group","wanted him to leave","were competing with him"]',1,'Belonging.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-ssat-reading-389','SSAT','reading','mcq',4,'Every morning before sunrise, Tomás walked to the harbor to help his uncle sort the night''s catch. At first the cold bit through his gloves and the smell made his eyes water. But as weeks passed he learned to tell a mackerel from a herring by touch alone, and the fishermen began to nod at him as one of their own. By spring, he no longer dreaded the alarm clock.','Which best describes how Tomás changes in the passage?',NULL,'["From uncomfortable to confident","From rich to poor","From angry to forgiving","From lazy to bored"]',0,'Discomfort → competence.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-ssat-reading-390','SSAT','reading','mcq',3,'Bridges are often built with arches because of how an arch handles weight. Instead of letting a load press straight down on a single span, an arch spreads the force outward along its curve and into the ground at each end. Engineers in ancient Rome used this principle to build aqueducts that still stand today, while flat beams of the same age have long since cracked.','What is the main purpose of the passage?',NULL,'["To describe the history of Rome","To explain why arches are strong","To compare bridges and aqueducts","To argue that beams are useless"]',1,'Explains arch strength.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-ssat-reading-391','SSAT','reading','mcq',4,'Bridges are often built with arches because of how an arch handles weight. Instead of letting a load press straight down on a single span, an arch spreads the force outward along its curve and into the ground at each end. Engineers in ancient Rome used this principle to build aqueducts that still stand today, while flat beams of the same age have long since cracked.','According to the passage, an arch handles weight by',NULL,'["pressing it straight down","spreading force along its curve into the ground","absorbing it with the beam","reflecting it upward"]',1,'Stated directly.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-ssat-reading-392','SSAT','reading','mcq',5,'Bridges are often built with arches because of how an arch handles weight. Instead of letting a load press straight down on a single span, an arch spreads the force outward along its curve and into the ground at each end. Engineers in ancient Rome used this principle to build aqueducts that still stand today, while flat beams of the same age have long since cracked.','What can be inferred about Roman aqueducts?',NULL,'["They were built with flat beams.","Their design has proven durable.","They no longer exist.","They were never used."]',1,'They still stand.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-ssat-reading-393','SSAT','reading','mcq',4,'Bridges are often built with arches because of how an arch handles weight. Instead of letting a load press straight down on a single span, an arch spreads the force outward along its curve and into the ground at each end. Engineers in ancient Rome used this principle to build aqueducts that still stand today, while flat beams of the same age have long since cracked.','The word "span" as used in the passage most nearly means',NULL,'["a length of time","the part of a bridge between supports","a small insect","to cross over"]',1,'Bridge section.',1,0);
