INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-math-441','ISEE','math','mcq',1,NULL,'The sum of three consecutive integers is 57. What is the greatest of the three integers?',NULL,'["19","18","21","20"]',3,'The middle integer is 19, so the greatest is 20.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-math-442','ISEE','math','mcq',2,NULL,'The ratio of boys to girls in a class is 5:4. If there are 15 boys, how many girls are there?',NULL,'["7","19","12","17"]',2,'15 ÷ 5 = 3 groups, and 3 × 4 = 12.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-math-443','ISEE','math','mcq',3,NULL,'What is 1/4 of 24?',NULL,'["19","10","4","6"]',3,'24 ÷ 4 × 1.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-math-444','ISEE','math','mcq',1,NULL,'What is 3/5 of 30?',NULL,'["23","15","13","18"]',3,'30 ÷ 5 × 3.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-math-445','ISEE','math','mcq',2,NULL,'What is 1/3 of 9?',NULL,'["6","3","7","4"]',1,'9 ÷ 3 × 1.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-math-446','ISEE','math','mcq',3,NULL,'The ratio of boys to girls in a class is 2:6. If there are 6 boys, how many girls are there?',NULL,'["12","20","18","9"]',2,'6 ÷ 2 = 3 groups, and 3 × 6 = 18.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-math-447','ISEE','math','mcq',1,NULL,'The ratio of boys to girls in a class is 3:4. If there are 27 boys, how many girls are there?',NULL,'["39","36","31","13"]',1,'27 ÷ 3 = 9 groups, and 9 × 4 = 36.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-math-448','ISEE','math','mcq',2,NULL,'If 3x − 10 = -1, what is the value of x?',NULL,'["6","4","3","2"]',2,'Add 10, divide by 3.',1,0);
INSERT OR IGNORE INTO questions (id,exam_type,section,kind,difficulty,passage,stem,image_svg,choices,answer,explanation,active,created_at) VALUES ('seed-isee-math-449','ISEE','math','mcq',3,NULL,'The sum of three consecutive integers is 42. What is the greatest of the three integers?',NULL,'["13","16","14","15"]',3,'The middle integer is 14, so the greatest is 15.',1,0);
